    {
      "name": "MvPolynomial.mem_restrictTotalDegree",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ (σ : Type u) {R : Type v} [inst : CommSemiring R] (m : ℕ) (p : MvPolynomial σ R),\n  p ∈ MvPolynomial.restrictTotalDegree σ R m ↔ p.totalDegree ≤ m"
