      "module_name": "Mathlib.RingTheory.Polynomial.Basic",
      "kind": "definition",
      "type": "(R : Type u) → [inst : Semiring R] → WithBot ℕ → Submodule R (Polynomial R)"
    },
    {
      "name": "MvPolynomial.instFiniteSubtypeMemSubmoduleRestrictTotalDegreeOfFinite",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "instance",
      "type": "∀ (σ : Type u) (R : Type v) [inst : CommSemiring R] [Finite σ] (N : ℕ),\n  Module.Finite R ↥(MvPolynomial.restrictTotalDegree σ R N)"
    },
    {
      "name": "MvPolynomial.degreesLE",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "definition",
      "type": "(R : Type u) → (σ : Type u_1) → [inst : CommSemiring R] → Multiset σ → Submodule R (MvPolynomial σ R)"
    },
    {
      "name": "MvPolynomial.mem_restrictDegree_iff_sup",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ (σ : Type u) {R : Type v} [inst : CommSemiring R] [inst_1 : DecidableEq σ] (p : MvPolynomial σ R) (n : ℕ),\n  p ∈ MvPolynomial.restrictDegree σ R n ↔ ∀ (i : σ), Multiset.count i p.degrees ≤ n"
    }
  ]
